svg.script:
const svg = document.querySelector("#points");

const N = 100;
const cx = 300;
const cy = 300;
const R = 200;

function randomInCircle() {
  const a = Math.random() * 2 * Math.PI;
  const r = Math.sqrt(Math.random()) * R;
  return {
    x: cx + r * Math.cos(a),
    y: cy + r * Math.sin(a)
  };
}

function spiralPoint(i) {
  // 2.5 turns
  const t = i / (N - 1);
  const turns = 2.5 * 2 * Math.PI * t;
  const radius = R * t;

  return {
    x: cx + radius * Math.cos(turns),
    y: cy + radius * Math.sin(turns)
  };
}

let points = [];

for (let i = 0; i < N; i++) {
  const p = randomInCircle();
  const sp = spiralPoint(i);

  const circle = document.createElementNS("http://www.w3.org/2000/svg", "circle");
  circle.setAttribute("r", 2);

  svg.appendChild(circle);

  points.push({
    el: circle,
    x: p.x,
    y: p.y,
    targetX: sp.x,
    targetY: sp.y,
    jitterSeed: Math.random() * 1000
  });
}

let t = 0;
let phase = 0; 
// 0 = random motion, 1 = transition to spiral

function animate() {
  t += 0.02;

  if (t > 4) phase = 1;

  points.forEach((p, i) => {
    if (phase === 0) {
      // random drifting motion
      const angle = t + p.jitterSeed;
      p.x += Math.cos(angle) * 0.5;
      p.y += Math.sin(angle * 1.3) * 0.5;

      // keep inside circle
      const dx = p.x - cx;
      const dy = p.y - cy;
      const dist = Math.sqrt(dx * dx + dy * dy);
      if (dist > R) {
        p.x = cx + dx / dist * R;
        p.y = cy + dy / dist * R;
      }

    } else {
      // smooth convergence
      p.x += (p.targetX - p.x) * 0.05;
      p.y += (p.targetY - p.y) * 0.05;
    }

    p.el.setAttribute("cx", p.x);
    p.el.setAttribute("cy", p.y);
  });

  requestAnimationFrame(animate);
}

animate();
